<?php require_once '../config.php'; if(!current_user()||current_user()['role']!=='admin')redirect('../login.php');$products=[];try{$products=db()->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();}catch(Throwable $e){}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products | Admin</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="index.php"><span class="brand-mark">✦</span><span><strong style="color:#fff">Golden Eggs</strong><small>Admin studio</small></span></a><nav style="margin-top:45px"><a href="index.php">Overview</a><a href="products.php">Products</a><a href="orders.php">Orders</a><a href="customers.php">Customers</a></nav></aside><main class="admin-main"><div class="eyebrow">Catalog</div><h1>Products.</h1><div class="summary"><table class="cart-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><?= e($product['name']) ?></td><td><?= e($product['category']) ?></td><td>KSh <?= number_format((float)$product['price']) ?></td><td><?= (int)$product['stock'] ?></td></tr><?php endforeach; ?></tbody></table></div></main></div></body></html>
